B.d2=new A.jl(1,"tip")
B.ae9=new A.dF([B.d2,"Spoel je glas eerst koud om","Een koud gespoeld glas zorgt voor een mooiere schuimkraag en voorkomt dat je bier te snel opwarmt.",null,"BierKompas",null])
B.adN=new A.dF([B.cJ,"Waarom heet het trappist?",'Een bier mag het logo "Authentic Trappist Product" alleen dragen als het onder toezicht van monniken binnen een trappistenabdij wordt gebrouwen.',null,null,null])
B.ae4=new A.dF([B.cI,"Amber Kompas IPA","Fris bitter met grapefruit en dennen, maar de moutbasis houdt alles mooi in balans. Een perfect terrasbier.",null,"Joris",4])
B.adP=new A.dF([B.d2,"Schenk schuin, eindig recht","Houd het glas schuin tijdens het inschenken en zet het halverwege rechtop. Zo krijg je een kraag van ongeveer twee vingers.",null,"BierKompas",null])
B.adV=new A.dF([B.cJ,"Bock komt uit Einbeck","De naam bockbier is waarschijnlijk een verbastering van Einbeck, een Duitse stad die in de middeleeuwen bekend was om zijn sterke bier.",null,null,null])
B.adW=new A.dF([B.cI,"Donkere Molen Stout","Koffie, pure chocolade en een fluweelzachte mondvulling. Laat hem iets opwarmen, dan komt de vanille los.",null,"Fatima",4.5])
B.aec=new A.dF([B.d2,"Niet elk bier hoort ijskoud","Pils smaakt het best rond 3 tot 5 graden, maar dubbels, tripels en stouts komen pas echt tot hun recht rond 8 tot 12 graden.",null,"BierKompas",null])
B.aeb=new A.dF([B.cJ,"Hop is familie van hennep","Hop en hennep horen allebei bij de plantenfamilie Cannabaceae. Hop geeft bier bitterheid, aroma en een langere houdbaarheid.",null,null,null])
B.ae3=new A.dF([B.cI,"Zomerhaven Witbier","Troebel, met citrus en koriander. Iets te zoet naar mijn smaak, maar heerlijk als het buiten 25 graden is.",u.g,"Daan",3.5])
B.ae0=new A.dF([B.d2,"Bewaar flessen rechtop","Rechtop, koel en donker bewaard blijft bier langer goed. Licht kan zorgen voor een onaangename, muffe smaak.",null,"BierKompas",null])
B.adX=new A.dF([B.cJ,"Spontane vergisting","Lambiek wordt spontaan vergist met wilde gisten en bacteri\xebn uit de lucht, traditioneel in de regio rond Brussel.","https://lh3.googleusercontent.com/aida-public/AB6AXuDknuVmwDTa5jB4wik1JsFZcg3HGHEguJ8tKYPIGvMOxeMgWo55nIZ92P0i_iTaZK5gCmhHDfSDDGd8HAgulU_Nt_waa4YIg1QNZCDQnGG9J70xbRh0XNaZFjxojqCPad3s7iiMSHzET5kRpj3GQcD9-hE4MuWtaKdUaP4Wkk6S1kxJhurPAITpPBmmuOIAnJ0_rU6wNjOB6JuYsppLKZZ370oFdfVTbvOpttwPVmC3aU02O1rJkSR2",null,null])
B.adS=new A.dF([B.cI,"Oude Sluis Dubbel","Rozijnen, bruine suiker en een vleugje drop. Een klassieke dubbel zonder poespas.",null,"Emma",4])
B.adY=new A.dF([B.d2,"Stout bij chocolade","De geroosterde tonen van een stout versterken een chocoladedessert. Probeer het eens met een brownie.",null,"BierKompas",null])
B.ae8=new A.dF([B.cJ,"Gueuze is een blend","Gueuze ontstaat door jonge en oude lambiek te mengen en op fles na te laten gisten. Daardoor krijgt het zijn bruisende, zure karakter.",null,null,null])
B.adU=new A.dF([B.cI,"Veldkers Saison","Droog, peperig en licht fruitig. Elke slok maakt dorst naar de volgende.",null,"Luuk",4.5])
